// The http-errors module-init shape, reduced to a committed fixture.
//
// http-errors (and therefore express, router, send, body-parser and
// serve-static) does two things at module scope that the island used to
// get wrong:
//
//   1. `require('depd')('http-errors')` — depd walks V8's STRUCTURED stack
//      (Error.prepareStackTrace returning the raw frames, captured with
//      Error.captureStackTrace) and calls `callSite.isEval()` on frame 1.
//      quickjs-ng ships CallSite with only the accessors its own trace
//      text needs, so isEval was undefined and the call died with
//      "not a function" before http-errors exported anything.
//   2. builds an HttpError class hierarchy with inherits() +
//      Object.setPrototypeOf() over real Error instances.
//
// Both are reproduced here WITHOUT vendoring the real packages: mini-depd
// below is the same stack walk, and the error hierarchy is the same
// inherits + setPrototypeOf composition. Paths and line numbers are never
// printed (they differ between the Node oracle and the island) — the
// probe reports the SHAPE of every V8 CallSite accessor plus the values
// that carry no receiver information.
"use strict";

/* ---- mini-inherits (the `inherits` package's body) ---- */

function inherits(ctor, superCtor) {
  Object.defineProperty(ctor, "super_", {
    value: superCtor,
    writable: true,
    configurable: true,
  });
  Object.setPrototypeOf(ctor.prototype, superCtor.prototype);
}

/* ---- mini-depd: the structured stack walk that crashed ---- */

function prepareObjectStackTrace(obj, stack) {
  return stack;
}

function getStack() {
  var limit = Error.stackTraceLimit;
  var obj = {};
  var prep = Error.prepareStackTrace;
  Error.prepareStackTrace = prepareObjectStackTrace;
  Error.stackTraceLimit = Math.max(10, limit);
  Error.captureStackTrace(obj);
  var stack = obj.stack.slice(1);
  Error.prepareStackTrace = prep;
  Error.stackTraceLimit = limit;
  return stack;
}

// depd's callSiteLocation, verbatim in shape: the isEval() call on the
// third line is the exact expression that used to throw.
function callSiteLocation(callSite) {
  var file = callSite.getFileName() || "<anonymous>";
  var line = callSite.getLineNumber();
  var colm = callSite.getColumnNumber();
  if (callSite.isEval()) {
    file = callSite.getEvalOrigin() + ", " + file;
  }
  var site = [file, line, colm];
  site.callSite = callSite;
  site.name = callSite.getFunctionName();
  return site;
}

// depd's own entry point: namespace in, deprecate function out. Reaching
// the return at all is the regression this fixture pins.
function depd(namespace) {
  if (!namespace) throw new TypeError("argument namespace is required");
  var site = callSiteLocation(getStack()[1]);
  function deprecate(message) {
    // depd asks the process emitter before printing anything.
    var count =
      typeof process.listenerCount !== "function"
        ? process.listeners("deprecation").length
        : process.listenerCount("deprecation");
    return namespace + ": " + message + " (listeners=" + count + ")";
  }
  deprecate._file = site[0];
  deprecate._namespace = namespace;
  return deprecate;
}

/* ---- the CallSite accessor surface, as a shape report ---- */

// Every accessor depd, stack-trace-style loggers, and V8 itself expose.
var ACCESSORS = [
  "getThis",
  "getTypeName",
  "getFunction",
  "getFunctionName",
  "getMethodName",
  "getFileName",
  "getLineNumber",
  "getColumnNumber",
  "getEvalOrigin",
  "getScriptNameOrSourceURL",
  "isToplevel",
  "isEval",
  "isNative",
  "isConstructor",
  "isAsync",
  "isPromiseAll",
  "getPromiseIndex",
  "toString",
];

// Frame 0 — this function's OWN frame. Not frame 1: under Node these
// probes are called from the ES module body, but in a compiled binary the
// call enters the island straight from the static side, so there is no
// caller frame above. Frame 0 exists on both lanes.
function describeFrame() {
  var cs = getStack()[0];
  var out = [];
  // 1. every accessor EXISTS and is callable without throwing.
  for (var i = 0; i < ACCESSORS.length; i++) {
    var name = ACCESSORS[i];
    var kind = typeof cs[name];
    var called;
    try {
      cs[name]();
      called = "ok";
    } catch (e) {
      called = "THREW " + e.message;
    }
    out.push(name + ":" + kind + ":" + called);
  }
  return out;
}

// The values that carry no receiver/eval information, so the island and
// Node must agree on them exactly. (getTypeName and isToplevel are
// derived from the frame's RECEIVER, which the island does not retain —
// they are deliberately not asserted here.)
function frameValues() {
  var cs = getStack()[0];
  return [
    "isEval=" + cs.isEval(),
    "isNative=" + cs.isNative(),
    "isConstructor=" + cs.isConstructor(),
    "isAsync=" + cs.isAsync(),
    "isPromiseAll=" + cs.isPromiseAll(),
    "getPromiseIndex=" + cs.getPromiseIndex(),
    "getMethodName=" + cs.getMethodName(),
    "getEvalOrigin=" + cs.getEvalOrigin(),
    "getThis=" + cs.getThis(),
    "fileName=" + typeof cs.getFileName(),
    "lineNumber=" + typeof cs.getLineNumber(),
    "columnNumber=" + typeof cs.getColumnNumber(),
    "scriptName=" + typeof cs.getScriptNameOrSourceURL(),
    "toString=" + typeof cs.toString(),
  ];
}

/* ---- mini-http-errors: inherits + setPrototypeOf over Error ---- */

function HttpError() {
  throw new TypeError("cannot construct abstract class");
}
inherits(HttpError, Error);

function makeErrorClass(name, code, expose) {
  function CodeError(message) {
    var msg = message != null ? message : name;
    var err = new Error(msg);
    Error.captureStackTrace(err, CodeError);
    Object.setPrototypeOf(err, CodeError.prototype);
    Object.defineProperty(err, "message", {
      enumerable: true,
      configurable: true,
      value: msg,
      writable: true,
    });
    Object.defineProperty(err, "name", {
      enumerable: false,
      configurable: true,
      value: name,
      writable: true,
    });
    return err;
  }
  inherits(CodeError, HttpError);
  var desc = Object.getOwnPropertyDescriptor(CodeError, "name");
  if (desc && desc.configurable) {
    desc.value = name;
    Object.defineProperty(CodeError, "name", desc);
  }
  CodeError.prototype.status = code;
  CodeError.prototype.statusCode = code;
  CodeError.prototype.expose = expose;
  return CodeError;
}

var NotFoundError = makeErrorClass("NotFoundError", 404, true);
var InternalServerError = makeErrorClass("InternalServerError", 500, false);

// The module-scope depd call: this line is what used to abort the load.
var deprecate = depd("callsitezoo");

function describeError(err) {
  return [
    err.message,
    err.name,
    err.status,
    err.statusCode,
    err.expose,
    err instanceof Error,
    err instanceof HttpError,
    err instanceof NotFoundError,
  ].join("|");
}

// Plain `exports.X =` assignments: the form cjs-module-lexer reads for
// named-export interop on both sides of the differential.
exports.deprecateNamespace = deprecate._namespace;
exports.deprecateFileIsString = typeof deprecate._file === "string";
exports.deprecateMessage = deprecate("old thing");
exports.describeFrame = describeFrame;
exports.frameValues = frameValues;
exports.NotFoundError = NotFoundError;
exports.InternalServerError = InternalServerError;
exports.HttpError = HttpError;
exports.describeError = describeError;
